import { useEffect, useState } from "react";

export default function Enquiries() {
  const [enquiries, setEnquiries] = useState([]);
  const [loading, setLoading] = useState(true);

  // ================= FETCH ENQUIRIES =================
  const fetchEnquiries = async () => {
    try {
      const res = await fetch("http://localhost:5001/admin/enquiries", {
        headers: {
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
      });
      const data = await res.json();
      setEnquiries(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEnquiries();
  }, []);

  // ================= UPDATE STATUS =================
  const updateStatus = async (id, status) => {
    try {
      await fetch(`http://localhost:5001/admin/enquiries/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("adminToken"),
        },
        body: JSON.stringify({ status }),
      });

      // 🔥 instant UI update
      setEnquiries((prev) =>
        prev.map((e) =>
          e.id === id ? { ...e, status } : e
        )
      );
    } catch (err) {
      console.error(err);
    }
  };

  // ================= UI =================
  return (
    <div className="p-10 text-white">
      <h1 className="text-3xl font-bold text-yellow-400 mb-8">
        Customer Enquiries
      </h1>

      {loading ? (
        <p className="text-gray-400">Loading enquiries...</p>
      ) : enquiries.length === 0 ? (
        <p className="text-gray-500">No enquiries found</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {enquiries.map((e) => (
            <div
              key={e.id}
              className="bg-[#0d0d0d] border border-yellow-500/30 rounded-2xl p-6 shadow-lg"
            >
              {/* Header */}
              <div className="flex justify-between items-center mb-3">
                <h2 className="text-lg font-semibold text-yellow-400">
                  {e.name}
                </h2>
                <span
                  className={`text-xs px-3 py-1 rounded-full ${
                    e.status === "New"
                      ? "bg-blue-500/20 text-blue-400"
                      : e.status === "Contacted"
                      ? "bg-yellow-500/20 text-yellow-400"
                      : e.status === "Joined"
                      ? "bg-green-500/20 text-green-400"
                      : "bg-red-500/20 text-red-400"
                  }`}
                >
                  {e.status}
                </span>
              </div>

              {/* Details */}
              <div className="text-sm text-gray-300 space-y-1 mb-3">
                <p><span className="text-gray-400">Phone:</span> {e.phone}</p>
                <p><span className="text-gray-400">Email:</span> {e.email}</p>
                <p><span className="text-gray-400">Branch:</span> {e.branch}</p>
                <p><span className="text-gray-400">Intent:</span> {e.intent}</p>
              </div>

              {/* Message */}
              <p className="text-gray-300 text-sm bg-black/40 p-3 rounded-lg mb-3">
                {e.message}
              </p>

              {/* Date */}
              <p className="text-xs text-gray-500 mb-4">
                {new Date(e.created_at).toLocaleString()}
              </p>

              {/* Actions */}
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={() => updateStatus(e.id, "Contacted")}
                  className="px-3 py-1 bg-yellow-500 text-black text-xs rounded-lg font-semibold hover:bg-yellow-600"
                >
                  Contacted
                </button>

                <button
                  onClick={() => updateStatus(e.id, "Joined")}
                  className="px-3 py-1 bg-green-500 text-black text-xs rounded-lg font-semibold hover:bg-green-600"
                >
                  Joined
                </button>

                <button
                  onClick={() => updateStatus(e.id, "Closed")}
                  className="px-3 py-1 bg-red-500 text-black text-xs rounded-lg font-semibold hover:bg-red-600"
                >
                  Closed
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
